WITH src AS (SELECT *, LENGTH(product_name) AS product_name_length FROM products WHERE brand NOT IN ('Umbrella', 'Acme')), products_stats AS (SELECT DATE_TRUNC('MONTH', launch_date) AS launch_month, CASE WHEN stock_qty >= 407 THEN 'high' WHEN stock_qty >= 70 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, COUNT(CASE WHEN brand = 'Initech' THEN 1 END) AS initech_count, ROUND((100 * SUM(CASE WHEN brand = 'Umbrella' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_umbrella FROM src GROUP BY DATE_TRUNC('MONTH', launch_date), CASE WHEN stock_qty >= 407 THEN 'high' WHEN stock_qty >= 70 THEN 'mid' ELSE 'low' END) SELECT launch_month, stock_qty_bucket, initech_count, pct_umbrella FROM products_stats WHERE pct_umbrella > 34 ORDER BY stock_qty_bucket, initech_count DESC;
